      "choices": [
        {
          "is_correct": false,
          "letter": "A",
          "tag": "Saying Fits",
          "text": "Fatima was a mathematician who often thought about unsolved problems of mathematics, although it was unpleasant to be reminded that most would probably remain unsolved in her lifetime. As the saying goes, “Strange how much you’ve got to know before you know how little you know.”"
        },
        {
          "is_correct": false,
